package hu.synostream.android;
import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.io.*;
@RunWith(AndroidJUnit4.class) public class Android0520Test {
 final Android050FlowTest f=new Android050FlowTest();JSONObject other;String primary;
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");AppUpdates.get(f.context).automatic(false);AppUpdates.get(f.context).checked=true;f.context.getSharedPreferences("recommendations",0).edit().clear().putBoolean("prefer_hu",false).commit();RecommendationsUi.factory=key->(endpoint,p)->{if(endpoint.endsWith("/translations"))return new JSONObject().put("translations",new JSONArray());long seed=Long.parseLong(endpoint.split("/")[1]);JSONArray rows=new JSONArray();long start=seed==10?10:110;for(long id=start;id<start+30;id++)rows.put(new JSONObject().put("id",id).put("title","Rec"+id).put("name","Rec"+id).put("overview","Fixture description").put("release_date","2020-01-01"));return new JSONObject().put("results",rows);};}
 @After public void cleanup()throws Exception{MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->{if(a!=null&&a.recommendationsUi!=null)a.recommendationsUi.close();f.app.automaticForeground(false);f.app.cancelScan();});RecommendationsUi.factory=key->(endpoint,p)->new TmdbApi(key,null).get(endpoint,p);f.cleanup();}
 void waitFor(java.util.function.BooleanSupplier test)throws Exception{long end=android.os.SystemClock.elapsedRealtime()+15000;while(!test.getAsBoolean()&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(50);assertTrue("Recommendations did not finish",test.getAsBoolean());}
 void cache(JSONObject library,Library.Card card)throws Exception{File file=f.app.cacheFile(library);file.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(file)){out.write(new JSONArray().put(card.json()).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
 void setup(FakeNas nas)throws Exception{Library.Card seed=new Library.Card("/Movies/Demo.Movie.2020.mkv","Seed fixture",true);seed.id=10;f.setup(nas,List.of(seed));primary=f.app.selectedLibrary;f.app.store.secret("tmdb_key","fixture-key");cache(f.app.selected(),seed);other=new JSONObject().put("id","other-fixture").put("name","Other").put("movie",true).put("paths",new JSONArray().put("/Other"));f.instrumentation.runOnMainSync(()->f.app.libraries.put(other));Library.Card owned=new Library.Card("/Other/Other.mkv","Other fixture",true);owned.id=11;cache(other,owned);}
 void open()throws Exception{f.click("tab_recommendations");waitFor(()->f.activity().recommendationsUi!=null&&!f.activity().recommendationsUi.loading&&!f.activity().recommendationsUi.batch.isEmpty());}
 @Test public void recommendationsReplaceFoldersExcludeOwnedAndKeepFeedbackPerLibrary()throws Exception{try(FakeNas nas=new FakeNas()){setup(nas);assertFalse(f.device.hasObject(By.text("Mappa szerint")));open();RecommendationsUi ui=f.activity().recommendationsUi;assertTrue(ui.batch.stream().noneMatch(i->i.optLong("id")==10||i.optLong("id")==11));JSONObject chosen=ui.batch.get(0);long id=chosen.optLong("id");String title=chosen.optString("title");assertTrue(f.device.wait(Until.hasObject(By.desc("Érdekel: "+title)),5000));f.device.findObject(By.desc("Érdekel: "+title)).click();f.click("rec_interested_tab");assertTrue(f.device.wait(Until.hasObject(By.text(title)),5000));f.device.takeScreenshot(new File(f.context.getExternalFilesDir(null),"recommendations-saved.png"));MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->a.select(other));waitFor(()->a.recommendationsUi!=null&&!a.recommendationsUi.loading&&a.recommendationsUi.libraryId.equals("other-fixture")&&!a.recommendationsUi.batch.isEmpty());assertTrue(a.recommendationsUi.engine.feedback("interested",Set.of()).isEmpty());f.instrumentation.runOnMainSync(()->a.select(LibraryConfig.defaultLibrary(f.app.libraries,true)));waitFor(()->a.recommendationsUi.libraryId.equals(primary)&&!a.recommendationsUi.loading);f.click("rec_interested_tab");assertTrue(f.device.wait(Until.hasObject(By.text(title)),5000));assertEquals(id,a.recommendationsUi.engine.feedback("interested",Set.of()).get(0).optLong("id"));}}
 @Test public void newBatchRotatesAndBackReturnsToLibrary()throws Exception{try(FakeNas nas=new FakeNas()){setup(nas);open();Set<String> prior=f.activity().recommendationsUi.previous();f.click("recommendations_next");waitFor(()->!f.activity().recommendationsUi.loading);assertTrue(f.activity().recommendationsUi.batch.stream().noneMatch(i->prior.contains(Recommendations.key(i))));f.device.takeScreenshot(new File(f.context.getExternalFilesDir(null),"recommendations-discover.png"));f.device.pressBack();assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/poster_grid")),5000));}}
 @Test public void missingTmdbKeyHasAnActionableMessage()throws Exception{try(FakeNas nas=new FakeNas()){setup(nas);f.app.store.secret("tmdb_key","");f.click("tab_recommendations");assertTrue(f.device.wait(Until.hasObject(By.textContains("TMDB API-kulcsodat")),5000));assertFalse(f.activity().recommendationsUi.loading);}}
}
